// Writes THIRD-PARTY-LICENSES.txt beside each built fixture: the name, version,
// licence identifier and full licence text of every npm package whose code is
// in that build. MIT, BSD, ISC and Apache-2.0 all require the notice to travel
// with redistributed code, and these builds are redistributed in this repo.
//
// The package list comes from .bundled-packages.json (written by
// record-packages.mjs during a Vite build) or, for toolchains with no such
// hook, from the hand-kept list in licenses.manual.json. Angular extracts its
// own (3rdpartylicenses.txt) and is copied as is.
//
// A package with a licence outside the allowlist, or with no licence text,
// fails the build: nothing copyleft or unlicensed may be vendored (ADR 0010).
import { copyFileSync, existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const srcRoot = join(here, '..');
const builtRoot = join(here, '..', '..', 'built');
const manual = JSON.parse(readFileSync(join(here, 'licenses.manual.json'), 'utf8'));
const allowed = /^(MIT|ISC|BSD-2-Clause|BSD-3-Clause|Apache-2\.0|0BSD|BlueOak-1\.0\.0|CC0-1\.0|\(MIT OR Apache-2\.0\)|MIT OR Apache-2\.0)$/;

function findPackage(fixture, name) {
  // npm hoists, but a package may also sit nested under another one.
  const roots = [join(srcRoot, fixture, 'node_modules')];
  for (const root of roots) {
    const dir = join(root, name);
    if (existsSync(join(dir, 'package.json'))) return dir;
  }
  return null;
}

function licenceText(dir) {
  const file = readdirSync(dir).find((f) => /^(licen[sc]e|copying)(\.(md|txt|markdown))?$/i.test(f));
  return file ? readFileSync(join(dir, file), 'utf8').trim() : null;
}

let failed = false;
const summary = [];
for (const [output, spec] of Object.entries(manual.outputs)) {
  const outDir = join(builtRoot, output);
  if (!existsSync(outDir)) {
    console.error(`licenses: built/${output} is missing`);
    failed = true;
    continue;
  }
  const dest = join(outDir, 'THIRD-PARTY-LICENSES.txt');
  if (spec.copy) {
    copyFileSync(join(srcRoot, spec.fixture, spec.copy), dest);
    summary.push(`${output}: copied ${spec.copy}`);
    continue;
  }
  const recorded = join(srcRoot, spec.fixture, '.bundled-packages.json');
  const names = new Set(spec.packages ?? []);
  if (existsSync(recorded)) for (const n of JSON.parse(readFileSync(recorded, 'utf8'))) names.add(n);
  if (names.size === 0) {
    console.error(`licenses: no package list for ${output}`);
    failed = true;
    continue;
  }
  const blocks = [];
  for (const name of [...names].sort()) {
    const dir = findPackage(spec.fixture, name);
    if (!dir) {
      console.error(`licenses: ${output}: package ${name} is not installed`);
      failed = true;
      continue;
    }
    const pkg = JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8'));
    const id = typeof pkg.license === 'string' ? pkg.license : pkg.license?.type;
    const text = licenceText(dir);
    if (!id || !allowed.test(id)) {
      console.error(`licenses: ${output}: ${name}@${pkg.version} has licence ${id}, which is not on the allowlist`);
      failed = true;
      continue;
    }
    if (!text) {
      console.error(`licenses: ${output}: ${name}@${pkg.version} ships no licence text`);
      failed = true;
      continue;
    }
    blocks.push(`${name}@${pkg.version}\nLicense: ${id}\n\n${text}`);
  }
  const head =
    `Third-party software in this build (${output}).\n` +
    `Generated by testdata/frameworks/src/_shared/licenses.mjs; do not edit.\n`;
  writeFileSync(dest, head + '\n' + blocks.join('\n\n' + '-'.repeat(72) + '\n\n') + '\n');
  summary.push(`${output}: ${blocks.length} package(s)`);
}
console.log(summary.join('\n'));
if (failed) process.exit(1);
